arguments.command:
curl -s "https://api.box.com/2.0/folders/100/items?limit=200" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d.get('entries',[]):
    if e['type']=='file':
        ext=e['name'].rsplit('.',1)[-1] if '.' in e['name'] else ''
        if ext.lower()=='pdf':
            print(e['id'], e['name'], '| owner:', e.get('owned_by',{}).get('name'), '| modified_by:', e.get('modified_by',{}).get('name'), '| modified:', e.get('modified_at'))
    else:
        print('FOLDER:', e['id'], e['name'])
"

